namespace StockWindow {
 static class Json {
  public static JavaScriptSerializer New(){return new JavaScriptSerializer { MaxJsonLength=32*1024*1024 };}
  public static Dictionary<string,object> Read(string value){return New().Deserialize<Dictionary<string,object>>(value);}
  public static string Text(IDictionary<string,object> d,string key){object v;return d!=null&&d.TryGetValue(key,out v)&&v!=null?Convert.ToString(v):"";}
  public static int Num(IDictionary<string,object> d,string key){int n;return Int32.TryParse(Text(d,key),out n)?n:0;}
  public static bool Bool(IDictionary<string,object> d,string key){return Text(d,key).ToLowerInvariant()=="true";}
  public static Dictionary<string,object> Obj(IDictionary<string,object>d,string key){object v;return d!=null&&d.TryGetValue(key,out v)?v as Dictionary<string,object>:null;}
  public static IEnumerable<object> List(IDictionary<string,object>d,string key){object v;return d!=null&&d.TryGetValue(key,out v)&&v is System.Collections.IEnumerable&&!(v is string)?((System.Collections.IEnumerable)v).Cast<object>():Enumerable.Empty<object>();}
 }
 // 固定色块进度，无系统主题扫光或跑马灯；任务结束后不会继续播放动画。
 sealed class PlainProgress : Control {
  int value;
  public int Value {get{return value;}set{this.value=Math.Max(0,Math.Min(100,value));Invalidate();}}
  public PlainProgress(){DoubleBuffered=true;SetStyle(ControlStyles.ResizeRedraw,true);AccessibleRole=AccessibleRole.ProgressBar;AccessibleName="任务进度";}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var rect=ClientRectangle;e.Graphics.Clear(SystemColors.ControlLight);int width=Math.Max(0,(rect.Width-2)*value/100);if(width>0)using(var brush=new SolidBrush(Color.FromArgb(36,151,64)))e.Graphics.FillRectangle(brush,1,1,width,Math.Max(0,rect.Height-2));if(rect.Width>0&&rect.Height>0)e.Graphics.DrawRectangle(SystemPens.ControlDark,0,0,rect.Width-1,rect.Height-1);}
 }
