  static string NormalizeQwenBaseURL(string value){
   string raw=String.IsNullOrWhiteSpace(value)?DefaultQwenBaseURL:value.Trim();Uri uri;
   string message="千问Base URL无效，请复制控制台中间的OpenAI兼容地址（https://…/compatible-mode/v1）。";
   if(!Uri.TryCreate(raw,UriKind.Absolute,out uri)||uri.Scheme!="https"||!uri.IsDefaultPort||uri.UserInfo.Length>0||uri.Query.Length>0||uri.Fragment.Length>0||System.Text.RegularExpressions.Regex.IsMatch(raw,@"[\s\\?#]"))throw new Exception(message);
   string[] shared={"dashscope.aliyuncs.com","dashscope-intl.aliyuncs.com","dashscope-us.aliyuncs.com","cn-hongkong.dashscope.aliyuncs.com"};
   bool dedicated=System.Text.RegularExpressions.Regex.IsMatch(uri.Host,@"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.(?:cn-beijing|ap-southeast-1|ap-northeast-1|eu-central-1|us-east-1|cn-hongkong)\.maas\.aliyuncs\.com$");
   if(!shared.Contains(uri.Host)&&!dedicated||!System.Text.RegularExpressions.Regex.IsMatch(uri.AbsolutePath,@"^/compatible-mode/v1/?$"))throw new Exception(message);
   return uri.GetLeftPart(UriPartial.Authority)+"/compatible-mode/v1";
  }
