  static string ResolveBatch(string value){
   string dir=Path.GetFullPath(value);if(File.Exists(Path.Combine(dir,"run.json")))return dir;
   foreach(string f in new[]{Path.Combine(dir,"其他","归档清单.json"),Path.Combine(dir,"归档清单.json")})if(File.Exists(f)){var m=Json.Read(File.ReadAllText(f,Encoding.UTF8));string src=Json.Text(m,"sourceDirectory"),rf=Path.Combine(src,"run.json");if(!Path.IsPathRooted(src)||!File.Exists(rf))throw new Exception("项目原记录不存在，请选原脚本批次。");var r=ReadBatchInfo(src);if(Json.Text(r,"id")!=Json.Text(m,"batchId"))throw new Exception("任务目录身份不符。");return src;}
   throw new Exception("请选含run.json的脚本批次，或桌面的任务目录。");
  }
