  internal Dictionary<string,object> Request(string mode){
   if(!sectorRows.Commit())throw new Exception("板块名称有误，请检查列表后再开始。");
   if(!new[]{"login","check","browser"}.Contains(mode)){if(mode=="normal"||mode=="members"||mode=="capture"){if(Sectors().Count==0)throw new Exception("请至少点选一个今天选好的板块。");if(Sectors().Any(s=>s.IndexOfAny(new[]{',','，',';','；','\r','\n'})>=0))throw new Exception("每格只填一个板块，其他板块请点添加。");}else ResolveBatch(batchPath.Text.Trim());}
   var request=new Dictionary<string,object>{{"command","start"},{"model",SelectedModel()},{"qwenModel",SelectedQwenModel()},{"reasoningEffort",SelectedEffort()},{"reviewWorkers",SelectedReviewWorkers()},{"captureWorkers",CaptureWorkerCount},{"compactEvidence",SelectedEvidenceMode()!="full"},{"evidenceMode",SelectedEvidenceMode()},{"mode",mode},{"source",east.Checked?"eastmoney":"sina"},{"sectors",Sectors().ToArray()},{"limit",(int)limit.Value},{"allMembers",allMembers.Checked},{"memberPercent",usePercent.Checked?(object)memberPercent.Value:null},{"captureSeconds",(int)capture.Value},{"reviewSeconds",(int)review.Value},{"taskName",taskName.Text.Trim()},{"batchDirectory",batchPath.Text.Trim()}};
   if(SelectedModel()=="deepseek-flash"&&new[]{"normal","resume","review","check"}.Contains(mode)){if(String.IsNullOrWhiteSpace(apiKey.Text)&&String.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("DEEPSEEK_API_KEY")))throw new Exception("请填写DeepSeek API密钥；密钥仅本次窗口使用，不会保存。");if(apiKey.Text.Trim().Length>0)request["deepseekApiKey"]=apiKey.Text.Trim();}if(QwenModelIds.Contains(SelectedModel())&&new[]{"normal","resume","review","check"}.Contains(mode)){string purpose=QwenPurposeError(SelectedModel());if(purpose.Length>0)throw new Exception(purpose);request["qwenBaseUrl"]=NormalizeQwenBaseURL(qwenBaseUrl.Text);if(String.IsNullOrWhiteSpace(qwenKey.Text)&&String.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("DASHSCOPE_API_KEY")))throw new Exception("请填写独立千问API密钥；仅本次窗口使用，不保存。");if(qwenKey.Text.Trim().Length>0)request["qwenApiKey"]=qwenKey.Text.Trim();}return request;
  }
  internal void StartOperation(string mode){
   if(busy)return;try{var request=Request(mode);if(!File.Exists(node)||!File.Exists(Path.Combine(root,"script","gui-bridge.mjs")))throw new Exception("缺少现有脚本或Node环境，请保留项目目录，或重新构建窗口。");
    operationMode=mode;finished=false;stopping=pauseRequested=taskPaused=pauseCommandPending=false;waitId=0;SetBusy(true);integrationReviewPeak=0;lastSnapshot=null;logs.Clear();matchedStocks.Rows.Clear();copiedMatches.Clear();copyPressedCode="";matchedSignature="";matchedBox.Text="本轮符合：0只";captureStage.Text="采图：准备名单";reviewStage.Text="审核：等待完整图证";stage.Text="正在准备任务…";counts.Text="符合 0  |  淘汰 0  |  待审核 0";progress.Value=0;SaveSettings();
    if(TestStart!=null){TestStart(request);return;}generation++;int gen=generation;
    string backend=BackendOverride??Path.Combine(root,"script","gui-bridge.mjs");
    var info=new ProcessStartInfo {FileName=node,Arguments=QuoteArgument(backend),WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};
    if(BackendOverride!=null){info.EnvironmentVariables["SCREENING_GUI_TEST_ROOT"]=integrationOutput;info.EnvironmentVariables["SCREENING_GUI_TEST_SCENARIO"]=integrationScenario;}
    var p=new Process {StartInfo=info,EnableRaisingEvents=true};worker=p;
    string logsDir=Path.Combine(Path.GetDirectoryName(configFile),"logs");Directory.CreateDirectory(logsDir);logFile=Path.Combine(logsDir,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".log");
    p.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)Post(gen,delegate{try{HandleEvent(Json.Read(e.Data));}catch(Exception ex){Log("状态解析失败："+ex.Message+"；"+e.Data);}});};
    p.ErrorDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)Post(gen,delegate{Log(e.Data);});};
    p.Exited+=delegate{p.WaitForExit();int code=p.ExitCode;Post(gen,delegate{if(!finished){Log("后端退出码："+code);RecoverUnexpectedExit(gen,code);}p.Dispose();});};
    p.Start();p.StandardInput.AutoFlush=true;p.BeginOutputReadLine();p.BeginErrorReadLine();Send(request);
   }catch(Exception e){finished=true;SetBusy(false);stage.Text="未启动："+e.Message;Log(stage.Text);}
  }
  void RecoverUnexpectedExit(int gen,int code){
   string directory=Json.Text(lastSnapshot,"directory"),reviewFailure=Json.Text(Json.Obj(Json.Obj(lastSnapshot,"pipeline"),"review"),"error");if(directory.Length==0){Finish(new Dictionary<string,object>{{"exitCode",code==0?1:code},{"error","脚本意外退出，本次尚未保存选股记录。"}});return;}stop.Enabled=resume.Enabled=false;stage.Text="后端意外结束，正在把已保存进度补存桌面…";
   ThreadPool.QueueUserWorkItem(delegate{Dictionary<string,object> recovered=null;string failure="";try{var info=new ProcessStartInfo {FileName=node,Arguments=QuoteArgument(BackendOverride!=null?Path.Combine(root,"tests","gui-fixture-recover.mjs"):Path.Combine(root,"script","recover-batch.mjs"))+" "+QuoteArgument(directory)+" "+code,WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};if(BackendOverride!=null)info.EnvironmentVariables["SCREENING_GUI_TEST_ROOT"]=integrationOutput;using(var helper=Process.Start(info)){string output=helper.StandardOutput.ReadToEnd();string err=helper.StandardError.ReadToEnd();helper.WaitForExit();if(helper.ExitCode!=0)throw new Exception(output+err);recovered=Json.Read(output.Trim());}}catch(Exception e){failure=e.Message;}
    Post(gen,delegate{var result=new Dictionary<string,object>{{"exitCode",code==0?1:code},{"error","脚本意外退出（退出码"+code+"）。"+(failure.Length>0?"补存未完成："+failure:"已把最后保存的进度补存到桌面；未完成项仍待审核。")+(reviewFailure.Length>0?" 退出前审核错误："+reviewFailure:"")}};if(recovered!=null){result["archiveDirectory"]=Json.Text(recovered,"archiveDirectory");result["archiveError"]=Json.Text(recovered,"archiveError");result["snapshot"]=Json.Obj(recovered,"snapshot");}Finish(result);});});
  }
  static string QuoteArgument(string text){var b=new StringBuilder("\"");int slashes=0;foreach(char c in text){if(c=='\\'){slashes++;continue;}if(c=='\"'){b.Append('\\',slashes*2+1);b.Append(c);}else{b.Append('\\',slashes);b.Append(c);}slashes=0;}b.Append('\\',slashes*2);return b.Append('"').ToString();}
  void Post(int gen,Action action){if(IsDisposed||Disposing)return;try{BeginInvoke((Action)delegate{if(gen==generation&&!IsDisposed)action();});}catch(InvalidOperationException){}}
  void Send(Dictionary<string,object> command){try{if(TestSend!=null){TestSend(command);return;}if(worker!=null&&!worker.HasExited){byte[] bytes=Encoding.UTF8.GetBytes(serializer.Serialize(command)+"\n");worker.StandardInput.BaseStream.Write(bytes,0,bytes.Length);worker.StandardInput.BaseStream.Flush();}}catch(Exception e){Log("控制命令未送达："+e.Message);}}
  void StopWork(){if(!busy||stopping)return;stopping=true;stop.Enabled=false;UpdatePauseButton();stage.Text="正在停止并保存已有判定、截图和进度，请稍候…";Log(closing?"关闭窗口：请求停止并保存任务":"点击停止并保存：请求停止任务");Send(new Dictionary<string,object>{{"command","stop"}});}
  void UpdatePauseButton(){resume.Text=waitId>0?"完成，继续":pauseRequested?"继续":"暂停";resume.Enabled=busy&&!finished&&!stopping&&!pauseCommandPending&&(waitId>0||new[]{"normal","resume","review","capture","members"}.Contains(operationMode));}
  void PauseOrContinue(){
   if(!busy||stopping)return;
   if(waitId>0){Send(new Dictionary<string,object>{{"command","continue"},{"id",waitId}});resume.Enabled=false;stage.Text="已提交人工确认，正在检查当前页面…";return;}
   if(pauseCommandPending)return;pauseRequested=!pauseRequested;pauseCommandPending=true;UpdatePauseButton();stage.Text=pauseRequested?"正在暂停：已在途采图和审核保存后停下…":"正在继续当前任务剩余部分…";Send(new Dictionary<string,object>{{"command",pauseRequested?"pause":"resume"}});
  }
  void ShowPauseStatus(){if(pauseRequested&&waitId==0&&!stopping)stage.Text=taskPaused?"已暂停：结果和队列保留，点“继续”接着处理剩余部分。":"正在暂停：停止新增任务，等待已在途采图和审核保存…";}
  void SetBusy(bool value){busy=value;foreach(Control c in locked)c.Enabled=!value;start.Enabled=!value;stop.Enabled=value;if(!value){waitId=0;stopping=pauseRequested=taskPaused=pauseCommandPending=false;UpdateMode();}UpdatePauseButton();open.Enabled=true;}
  internal void HandleEvent(Dictionary<string,object> e){
   string type=Json.Text(e,"type");if(finished&&type!="log")return;if(type=="log")Log(Json.Text(e,"message"));else if(type=="error"){stage.Text="任务异常："+Json.Text(e,"message");Log(stage.Text);}
   else if(type=="progress"){lastSnapshot=e;ShowSnapshot(e);}
   else if(type=="waiting"){waitId=Json.Num(e,"id");UpdatePauseButton();captureStage.Text="采图：等待人工验证；审核继续";stage.Text="等待人工操作："+Json.Text(e,"message");Log(stage.Text);}
   else if(type=="waiting-ended"){waitId=0;UpdatePauseButton();stage.Text="人工确认已收到，继续检查页面…";ShowPauseStatus();}
   else if(type=="pause-state"){pauseRequested=Json.Bool(e,"requested");taskPaused=Json.Text(e,"status")=="paused";pauseCommandPending=false;UpdatePauseButton();if(!pauseRequested&&lastSnapshot!=null)ShowSnapshot(lastSnapshot);ShowPauseStatus();}
   else if(type=="started")Log("已开始："+Json.Text(e,"mode")+"；行情来源："+Json.Text(e,"source")+"；复核模型："+Json.Text(e,"model"));
   else if(type=="finished")Finish(e);
  }
  void ShowSnapshot(Dictionary<string,object> d){
