   if(waitId==0&&captureRows.Length>2)captureStage.Text="采图："+Json.Num(captureLane,"workers")+"路；运行"+Json.Num(captureLane,"active")+"，等人工"+captureRows.Count(v=>Json.Text(v,"status")=="waiting-manual")+"，等审核"+Json.Num(captureLane,"waitingForReview")+"；已保存图 "+Json.Num(d,"captured");tips.SetToolTip(captureStage,String.Join(Environment.NewLine,captureRows.Select(v=>"采图"+Json.Num(v,"id")+" "+Json.Text(v,"code")+" "+Json.Text(v,"detail"))));
   integrationReviewPeak=Math.Max(integrationReviewPeak,Json.Num(reviewLane,"activeWorkers"));
   integrationCapturePeak=Math.Max(integrationCapturePeak,Json.Num(captureLane,"active"));if(Json.Num(captureLane,"workers")>=2&&Json.Num(captureLane,"active")>=2)integrationDualCapture=true;
