   var matches=Json.List(d,"matches").Select(v=>v as Dictionary<string,object>).Where(v=>v!=null).ToArray();string signature=String.Join("|",matches.Select(v=>Json.Text(v,"code")+":"+Json.Text(v,"name")));if(signature!=matchedSignature){SyncMatches(matches);matchedSignature=signature;ResizeMatches();}matchedBox.Text="本轮符合："+matches.Length+"只";if(busy&&matches.Length>0&&Json.Text(captureLane,"status")=="running")integrationLiveMatches=true;

   int total=Json.Num(d,"total");if(waitId==0)stage.Text=Json.Text(d,"stage")+(total>0?String.Format("  已访问 {0}/{1}，已复核 {2}",Json.Num(d,"visited"),total,Json.Num(d,"reviewed")):"");
   progress.Value=total>0?Json.Num(d,"percent"):0;
   counts.Text=String.Format("符合 {0}  |  淘汰 {1}  |  待审核 {2}（未访问 {3}）  |  已保存图 {4}",Json.Num(d,"passed"),Json.Num(d,"eliminated"),Json.Num(d,"pending"),Json.Num(d,"unvisited"),Json.Num(d,"captured"));
