  void StyleMatchRow(DataGridViewRow row){
   bool copied=copiedMatches.Contains(Convert.ToString(row.Tag));row.Cells["copy"].Value=copied?"已复制":"复制";
   row.DefaultCellStyle.BackColor=copied?CopiedMatchColor:SystemColors.Window;row.DefaultCellStyle.ForeColor=copied?Color.White:SystemColors.ControlText;
   row.DefaultCellStyle.SelectionBackColor=copied?CopiedMatchSelectedColor:SystemColors.Highlight;row.DefaultCellStyle.SelectionForeColor=copied?Color.White:SystemColors.HighlightText;
  }
  void SyncMatches(Dictionary<string,object>[] matches){
   string selected=matchedStocks.CurrentRow==null?"":Convert.ToString(matchedStocks.CurrentRow.Tag),column=matchedStocks.CurrentCell==null?"name":matchedStocks.Columns[matchedStocks.CurrentCell.ColumnIndex].Name;
   int top=matchedStocks.FirstDisplayedScrollingRowIndex;string first=top>=0?Convert.ToString(matchedStocks.Rows[top].Tag):"";
   var wanted=new HashSet<string>(matches.Select(v=>Json.Text(v,"code")),StringComparer.Ordinal);var existing=matchedStocks.Rows.Cast<DataGridViewRow>().ToDictionary(r=>Convert.ToString(r.Tag),StringComparer.Ordinal);matchedStocks.SuspendLayout();
   try{
    for(int n=matchedStocks.Rows.Count-1;n>=0;n--)if(!wanted.Contains(Convert.ToString(matchedStocks.Rows[n].Tag)))matchedStocks.Rows.RemoveAt(n);
    for(int n=0;n<matches.Length;n++){
     string code=Json.Text(matches[n],"code"),name=Json.Text(matches[n],"name");DataGridViewRow row;existing.TryGetValue(code,out row);
     if(row==null){matchedStocks.Rows.Insert(n,name,code,"复制");row=matchedStocks.Rows[n];row.Tag=code;StyleMatchRow(row);}
     else if(row.Index!=n){matchedStocks.Rows.Remove(row);matchedStocks.Rows.Insert(n,row);}
     if(Convert.ToString(row.Cells["name"].Value)!=name)row.Cells["name"].Value=name;
    }
    var current=matchedStocks.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Convert.ToString(r.Tag)==selected);if(current!=null)matchedStocks.CurrentCell=current.Cells[column];else{matchedStocks.CurrentCell=null;matchedStocks.ClearSelection();}
    var visible=matchedStocks.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Convert.ToString(r.Tag)==first);if(visible!=null&&visible.Visible)matchedStocks.FirstDisplayedScrollingRowIndex=visible.Index;
   }finally{matchedStocks.ResumeLayout();}
  }
  void ResizeMatches(){if(matchedHost.ClientSize.Height<=0)return;int desired=matchedStocks.ColumnHeadersHeight+Math.Max(1,matchedStocks.Rows.Count)*matchedStocks.RowTemplate.Height+matchedBox.Font.Height+12;matchedBox.Height=Math.Min(matchedHost.ClientSize.Height,desired);}
  void MatchedClicked(object sender,DataGridViewCellEventArgs e){
   if(e.RowIndex<0||e.RowIndex>=matchedStocks.Rows.Count||e.ColumnIndex!=2)return;var row=matchedStocks.Rows[e.RowIndex];string code=Convert.ToString(row.Tag),name=Convert.ToString(row.Cells["name"].Value);if(copyPressedCode.Length>0&&copyPressedCode!=code){copyPressedCode="";return;}copyPressedCode="";if(name.Length==0)return;
   try{if(TestCopy!=null)TestCopy(name);else Clipboard.SetText(name,TextDataFormat.UnicodeText);copiedMatches.Add(code);StyleMatchRow(row);}catch(Exception ex){matchedBox.Text="本轮符合："+matchedStocks.Rows.Count+"只（复制失败）";Log("股票名未复制："+ex.Message);}
  }
  void Finish(Dictionary<string,object> e){
   finished=true;lastExitCode=Json.Num(e,"exitCode");lastStopped=Json.Bool(e,"stopped");var snap=Json.Obj(e,"snapshot")??lastSnapshot;if(snap!=null){lastSnapshot=snap;ShowSnapshot(snap);lastBatch=Json.Text(snap,"directory");foreach(var s in Json.List(snap,"sectors"))Remember(Convert.ToString(s));}
   if(snap!=null){captureStage.Text=Json.Text(Json.Obj(Json.Obj(snap,"pipeline"),"capture"),"status")=="disabled"?"采图：本次未采图，沿用原图 "+Json.Num(snap,"captured"):"采图："+(Json.Bool(e,"stopped")?"已停止":"已结束")+"；保存图 "+Json.Num(snap,"captured");reviewStage.Text="审核：已复核 "+Json.Num(snap,"reviewed")+"；本轮待审核 "+Json.Num(snap,"pending");}
   string archive=Json.Text(e,"archiveDirectory"),archiveError=Json.Text(e,"archiveError");
   lastArchive=archive;bool ok=Json.Num(e,"exitCode")==0,stopped=Json.Bool(e,"stopped");string detail=Json.Text(e,"error"),error=Json.Text(e,"errorSummary");if(error.Length==0)error=detail;if(error.Length==0)error=Json.Text(snap,"error");
   if(stopped)stage.Text=(snap!=null?"已停止，现有结果与进度已保存。":"已停止，本次尚未生成选股结果。")+(error.Length>0?" "+error:"");
   else if(ok){progress.Value=100;string mode=Json.Text(e,"mode");stage.Text=mode=="members"?"成分预览完成：仅列名单，没有开展选股。":mode=="capture"?"截图采集完成，尚未进行模型复核。":mode=="check"?"环境检查通过。":mode=="browser"?"浏览器启动测试通过。":mode=="login"?"人工登录完成，专用会话已保存。":"本轮执行完成，请查看结果数量。";if(mode=="members")counts.Text="候选名单 "+Json.Num(snap,"total")+" 只；本次未进行报价、采图或图形筛选。";}
   else stage.Text="本轮未完成："+(error.Length>0?error:"脚本返回失败（退出码 "+lastExitCode+"），请查看上方日志中的具体错误。");
   if(archiveError.Length>0){if(ok)stage.Text="本轮执行完成；桌面归档未完成："+archiveError;Log("桌面归档未完成："+archiveError);}
   if(detail.Length>0&&detail!=error)Log("失败详情："+detail);Log(stage.Text);if(archive.Length>0)Log("桌面归档位置："+archive);else if(snap!=null)Log("本轮尚无桌面归档；原始记录："+lastBatch);Log("打开结果文件夹："+resultDir);
   if(snap!=null&&Json.Text(snap,"status")=="members_only")foreach(var m in Json.List(snap,"members")){var d=m as Dictionary<string,object>;if(d!=null)Log(Json.Text(d,"code")+" "+Json.Text(d,"name"));}
   if(snap!=null&&lastBatch.Length>0)batchPath.Text=lastBatch;
   if(!ok&&!stopped&&snap!=null&&Json.Num(snap,"pending")>0&&lastBatch.Length>0)Log("已保留缺项，选择“继续任务”可从本轮缺项接着处理，沿用原名单范围。");
   SetBusy(false);LoadRecent();SaveSettings();if(closing)Close();
  }
  void Log(string message){if(String.IsNullOrEmpty(message))return;if(apiKey.Text.Trim().Length>0)message=message.Replace(apiKey.Text.Trim(),"[已隐藏密钥]");if(qwenKey.Text.Trim().Length>0)message=message.Replace(qwenKey.Text.Trim(),"[已隐藏密钥]");string qwenEnv=Environment.GetEnvironmentVariable("DASHSCOPE_API_KEY");if(!String.IsNullOrEmpty(qwenEnv))message=message.Replace(qwenEnv,"[已隐藏密钥]");string envKey=Environment.GetEnvironmentVariable("DEEPSEEK_API_KEY");if(!String.IsNullOrEmpty(envKey))message=message.Replace(envKey,"[已隐藏密钥]");string text=DateTime.Now.ToString("HH:mm:ss")+" "+message+Environment.NewLine;if(logs.TextLength>60000)logs.Text=logs.Text.Substring(logs.TextLength-40000);logs.AppendText(text);if(logFile.Length>0)try{File.AppendAllText(logFile,text,new UTF8Encoding(false));}catch{}}
