  internal void BeginIntegration(string action,string output){integrationOutput=output;integrationScenario=action;if(action.StartsWith("review-")){batchPath.Text=Environment.GetEnvironmentVariable("SCREENING_MODEL_TEST_BATCH")??"";modes["review"].PerformClick();SelectModel(action=="review-deepseek"?"deepseek-flash":action=="review-luna"?"gpt-6-luna":action=="review-terra"?"gpt-6.1-terra":"gpt-6.1-sol");taskName.Text="模型按钮验收_"+SelectedModel();review.Value=120;StartOperation("review");}else if(action=="members-percent"){AddSector("出版");AddSector("机器人概念");memberPercent.Value=30;usePercent.Checked=true;StartOperation("members");}else if(action=="members-all"){AddSector("机器人概念");AddSector("人形机器人");allMembers.Checked=true;StartOperation("members");}else if(action=="members"||action=="screen"){AddSector("物理AI");limit.Value=1;if(action=="screen"){taskName.Text="窗口功能验收";capture.Value=90;review.Value=90;}StartOperation(action=="members"?"members":"normal");}else if(action.StartsWith("fixture")){BackendOverride=Path.Combine(root,"tests",action.StartsWith("fixture-task-pause")?"gui-pause-bridge.mjs":action.StartsWith("fixture-pipeline")?"gui-pipeline-bridge.mjs":"gui-fixture-bridge.mjs");if(action.StartsWith("fixture-task-pause")){allMembers.Checked=true;SelectReviewWorkers(2);}if(action.StartsWith("fixture-pipeline")){limit.Value=8;int lanes=action=="fixture-pipeline"?1:Int32.Parse(action.Substring(action.LastIndexOf('-')+1));SelectReviewWorkers(lanes);allMembers.Checked=true;}AddSector("合成行业");taskName.Text="联通中文";if(action=="fixture-qwen"){SelectModel("qwen3.5-omni-flash");qwenKey.Text="fixture-qwen-secret";}else if(action=="fixture-deepseek"){SelectModel("deepseek-flash");apiKey.Text="fixture-memory-secret";}else if(action=="fixture-luna")SelectModel("gpt-6-luna");else if(action=="fixture-terra")SelectModel("gpt-6.1-terra");else SelectModel("gpt-6.1-sol");StartOperation("normal");}else StartOperation(action);}
  internal void DriveIntegration(){
   if(integrationScenario.StartsWith("fixture-task-pause")){
    if(!integrationPauseClicked&&Json.Num(lastSnapshot,"visited")>0&&resume.Enabled){integrationPauseClicked=true;resume.PerformClick();}
    else if(taskPaused&&!integrationPauseObserved){integrationPauseObserved=true;integrationPauseWatch.Start();}
    else if(integrationPauseObserved&&!integrationResumeSent&&integrationPauseWatch.ElapsedMilliseconds>=800){integrationResumeSent=true;if(integrationScenario.EndsWith("-stop"))stop.PerformClick();else resume.PerformClick();}
    return;
   }
   if(waitId>0&&resume.Enabled){if(integrationScenario=="fixture-stop"||integrationScenario=="screen")stop.PerformClick();else if(integrationScenario.StartsWith("fixture"))resume.PerformClick();}
  }
