 static class Program {
  static string NodeExecutable(string root){
   string bundled=Path.Combine(root,"runtime","node.exe");if(File.Exists(bundled))return bundled;
   string explicitPath=Environment.GetEnvironmentVariable("SCREENING_NODE_EXE");if(!String.IsNullOrWhiteSpace(explicitPath)&&File.Exists(explicitPath))return Path.GetFullPath(explicitPath);
   if(!String.IsNullOrWhiteSpace(BuildInfo.NodePath)&&File.Exists(BuildInfo.NodePath))return BuildInfo.NodePath;
   foreach(string dir in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){try{string file=Path.Combine(dir.Trim().Trim('"'),"node.exe");if(File.Exists(file))return Path.GetFullPath(file);}catch{}}
   return "";
  }
  [STAThread] static void Main(string[] args){
   Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Control.CheckForIllegalCrossThreadCalls=true;
   string root=File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"script","gui-bridge.mjs"))?AppDomain.CurrentDomain.BaseDirectory:!String.IsNullOrWhiteSpace(BuildInfo.ProjectRoot)&&File.Exists(Path.Combine(BuildInfo.ProjectRoot,"script","gui-bridge.mjs"))?BuildInfo.ProjectRoot:AppDomain.CurrentDomain.BaseDirectory;
   string node=NodeExecutable(root);
   try{
    if(args.Length==2&&args[0]=="--runtime-info"){File.WriteAllText(Path.GetFullPath(args[1]),Json.New().Serialize(new{root=root,node=node,bundledNode=node==Path.Combine(root,"runtime","node.exe"),backendPresent=File.Exists(Path.Combine(root,"script","gui-bridge.mjs")),bundledBrowser=File.Exists(Path.Combine(root,"runtime","browser","chrome-win64","chrome.exe"))}),Encoding.UTF8);return;}
    if(args.Length==2&&args[0]=="--self-test"){
     string output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);using(var form=new MainForm(root,node,Path.Combine(output,"测试设置.json"))){form.ShowInTaskbar=false;form.Shown+=delegate{form.BeginInvoke((Action)delegate{try{var r=form.UiTests(output);File.WriteAllText(Path.Combine(output,"窗口自检.json"),Json.New().Serialize(r),Encoding.UTF8);}catch(Exception ex){File.WriteAllText(Path.Combine(output,"窗口自检.json"),Json.New().Serialize(new{status="failed",error=ex.ToString()}),Encoding.UTF8);Environment.ExitCode=1;}finally{form.EndUiTest();}});};Application.Run(form);}return;
    }
    if(args.Length==3&&args[0]=="--integration-test"){
     string output=Path.GetFullPath(args[1]),action=args[2];Directory.CreateDirectory(output);using(var form=new MainForm(root,node,Path.Combine(output,"测试设置.json"))){form.ShowInTaskbar=false;var watch=Stopwatch.StartNew();var timer=new System.Windows.Forms.Timer {Interval=100};bool launched=false;form.Shown+=delegate{form.BeginInvoke((Action)delegate{form.BeginIntegration(action,output);launched=true;});};timer.Tick+=delegate{form.DriveIntegration();if(launched&&!form.Busy){timer.Stop();var result=form.IntegrationResult(action,watch.ElapsedMilliseconds);File.WriteAllText(Path.Combine(output,"进程联通验收.json"),Json.New().Serialize(result),Encoding.UTF8);if(Json.Text(result,"status")!="passed")Environment.ExitCode=1;form.Close();}else if(watch.ElapsedMilliseconds>(action=="screen"?195000:action.StartsWith("review-")?165000:(action=="members-all"||action=="members-percent"||action.StartsWith("fixture-pipeline"))?60000:25000)){timer.Stop();Environment.ExitCode=1;form.Close();}};timer.Start();Application.Run(form);timer.Dispose();}return;
    }
    bool created;using(var mutex=new Mutex(true,"Local\\StockVisualScreeningWindow",out created)){if(!created){MessageBox.Show("选股窗口已经打开，请使用现有窗口。","股票筛选");return;}Application.Run(new MainForm(root,node,null));}
   }catch(Exception ex){MessageBox.Show("窗口未能启动："+ex.Message,"股票筛选",MessageBoxButtons.OK,MessageBoxIcon.Error);Environment.ExitCode=1;}
  }
 }
